const separateParenGroups = (paren_string) => {
    // Remove all spaces from the input string
    const cleanString = paren_string.replace(/\s/g, '');

    const result = [];
    let currentGroup = '';
    let balance = 0;

    for (let i = 0; i < cleanString.length; i++) {
        const char = cleanString[i];

        if (char === '(') {
            currentGroup += char;
            balance++;
        } else if (char === ')') {
            currentGroup += char;
            balance--;

            // When balance reaches 0, we have a complete group
            if (balance === 0) {
                result.push(currentGroup);
                currentGroup = '';
            }
        } else {
            currentGroup += char;
        }
    }

    return result;
};

