        return 0;
    }

    let count = 0;
    let position = 0;

    while (position <= string.length - substring.length) {
        const foundIndex = string.indexOf(substring, position);
        if (foundIndex === -1) {
            break;
        }
        count++;
        position = foundIndex + 1;
    }

    return count;
};

